      add :canonical_slug,
          references(:brain_objects,
            column: :slug,
            type: :text,
            on_delete: :delete_all,
            on_update: :update_all
          ),
          null: false

      add :notes, :text
      add :created_at, :utc_datetime_usec, null: false, default: fragment("now()")
    end

    create unique_index(:brain_slug_aliases, [:alias_slug], name: :brain_slug_aliases_alias_key)

    create index(:brain_slug_aliases, [:canonical_slug], name: :brain_slug_aliases_canonical_idx)

    create constraint(:brain_slug_aliases, :brain_slug_aliases_no_self,
             check: "alias_slug <> canonical_slug"
           )

    comment_table(:brain_slug_aliases, "Stable redirects from retired slugs to current slugs.")
  end

  defp create_object_aliases do
