    create index(:brain_object_aliases, [:alias_norm], name: :brain_object_aliases_lookup_idx)
    create index(:brain_object_aliases, [:object_slug], name: :brain_object_aliases_object_idx)

    create constraint(:brain_object_aliases, :brain_object_aliases_alias_present,
             check: "btrim(alias_norm) <> ''"
           )

    comment_table(:brain_object_aliases, "Normalized natural-language aliases per object.")
