    create constraint(:brain_contradictions, :brain_contradictions_status_values,
             check: "status IN ('open', 'resolved', 'dismissed')"
           )

    create constraint(:brain_contradictions, :brain_contradictions_confidence_range,
             check: "confidence >= 0.0 AND confidence <= 1.0"
           )

    comment_table(:brain_contradictions, "Contradiction probe findings cache.")
