  # ── Search indexes ───────────────────────────────────────────────

  # The initial migration always builds with the default icu tokenizer; a
  # brain.search_tokenizer change rebuilds these two recoverable indexes at
  # runtime without touching the base tables.
  defp create_search_indexes do
    execute("""
    CREATE INDEX brain_chunks_bm25_idx
    ON brain_chunks
    USING bm25 (id, (chunk_text::pdb.icu))
    WITH (key_field='id')
    """)

    execute("""
    CREATE INDEX brain_claims_bm25_idx
    ON brain_claims
    USING bm25 (id, (claim::pdb.icu))
    WITH (key_field='id')
    """)
  end

  # ── Data backfills ───────────────────────────────────────────────

  # Brain owns instance-global model calls (embedding, extraction, dreaming)
  # and needs an accountable system Principal as their AIGateway subject.
  # Principal UIDs are caller-chosen text, so a human or agent may already
  # occupy `brain`; silently reusing it would misattribute every Brain model
  # call, its cost, and its audit trail to that identity. The upgrade fails
  # loudly instead and tells the operator to rename the existing principal.
  defp insert_brain_system_principal do
    %{rows: rows} =
      repo().query!("SELECT type FROM principals WHERE uid = 'brain'", [])

    case rows do
      [[type]] when type != "system" ->
        raise """
        principal uid 'brain' already exists with type '#{type}'. BrainV3 \
        reserves this uid for its system subject. Rename or delete that \
        principal, then run the upgrade again.\
        """

      _absent_or_system ->
        repo().query!(
          """
          INSERT INTO principals (uid, type, status, display_name, inserted_at, updated_at)
          VALUES ('brain', 'system', 'active', 'Brain', now(), now())
          ON CONFLICT (uid) DO NOTHING
          """,
          []
        )
    end
  end

  # Every human and agent Principal owns one canonical Object. Later Principal
  # and Agent creation transactions keep this invariant; this backfill covers
  # rows that exist before BrainV3.
  defp backfill_canonical_principal_objects do
    rows =
      repo().query!(
        """
        SELECT uid, type, display_name FROM principals
        WHERE type IN ('human', 'agent')
        """,
        []
      )

    Enum.each(rows.rows, fn [uid, type, display_name] ->
      slug =
        case type do
          "human" -> "people/#{uid}"
          "agent" -> "agents/#{uid}"
        end

      object_type =
        case type do
          "human" -> "person"
          "agent" -> "agent"
        end

      repo().query!(
        """
        INSERT INTO brain_objects (id, slug, type, subtype, title, body, meta, created_at, updated_at)
        VALUES ($1, $2, $3, 'internal', $4, '', '{}'::jsonb, now(), now())
        ON CONFLICT (slug) DO NOTHING
        """,
        [
          Ecto.UUID.dump!(Ankole.Ecto.UUIDv7.autogenerate()),
          slug,
          object_type,
          display_name || uid
        ]
      )
    end)
  end

  # ── SQL helpers ──────────────────────────────────────────────────

  defp scope_shape_sql(column) do
    "#{column} ~ '^(world|group:.+|principal:.+)$'"
  end

  defp embedding_state_sql do
    """
    (embedding IS NULL AND embedding_signature IS NULL AND embedding_error IS NULL AND embedded_at IS NULL)
    OR (embedding IS NOT NULL AND embedding_signature IS NOT NULL AND embedded_at IS NOT NULL AND embedding_error IS NULL)
    OR (embedding IS NULL AND embedding_signature IS NOT NULL AND embedding_error IS NOT NULL AND embedded_at IS NULL)
    """
  end

  defp claim_type_shape_sql do
    """
    (
      claim_type = 'fact'
      AND kind IN ('event', 'preference', 'commitment', 'belief', 'fact')
      AND notability IN ('high', 'medium', 'low')
      AND valid_from IS NOT NULL
      AND confidence IS NOT NULL AND confidence >= 0.0 AND confidence <= 1.0
      AND num_nonnulls(
        weight, since_date, until_date, active, graded_quality, graded_confidence,
        graded_at, resolved_at, resolved_outcome, resolved_quality, resolved_value,
        resolved_unit, resolution_provenance, resolved_by
      ) = 0
    )
    OR (
      claim_type = 'take'
      AND weight IS NOT NULL AND weight >= 0.0 AND weight <= 1.0
      AND active IS NOT NULL
      AND num_nonnulls(
        notability, context, valid_from, valid_until, expired_at, consolidated_at,
        consolidated_into, confidence, provenance_session, claim_metric, claim_value,
        claim_unit, claim_period, event_type, dimension, value, value_hash, dim_status
      ) = 0
    )
    """
  end

  defp comment_table(table, comment) do
    execute("COMMENT ON TABLE #{identifier(table)} IS #{literal(comment)}")
  end

  defp identifier(value), do: "\"" <> String.replace(to_string(value), "\"", "\"\"") <> "\""
  defp literal(value), do: "'" <> String.replace(value, "'", "''") <> "'"
end
